def pg(slug, title, meta, h1, lede, body, faq=None, feed=False):
    return {"route": f"/guides/{slug}/" if slug else "/guides/", "title": title, "meta_description": meta, "h1": h1, "kicker": "Guide", "lede": lede,
            "breadcrumbs": [("Home", "/"), ("Guides", "/guides/"), (h1[:40], None)] if slug else [("Home", "/"), ("Guides", None)],
            "body_html": body, "faq": faq or [], "article": True, "feed_item": feed}


def hub():
    body = p("Guides answer the questions that don't fit a service, a permit or a comparison page. Each one is written for Sarasota County's ground and rules, cites its sources, and links the next commercial step.")
    body += cards([(f"/guides/{s}/", t, x) for s, t, x in GUIDES])
    body += reviewed("September 10, 2026")
    return pg("", "Guides: Concrete & Pavers on the Sarasota Coast", "Fourteen guides for Sarasota County homeowners: why concrete cracks here, cure and rain, snowbird projects, deposits and warranties, verifying contractors, rust stains, polymeric sand, efflorescence, permeable pavers, golf carts, GDC lots, condo boards and insurance claims.",
              "Guides for concrete and pavers on the Sarasota coast", "Fourteen answers to the questions between the service pages, plus a weekly log of real ones.", body)


def cracks():
    faq = [("Why does concrete crack in Sarasota?", "Three reasons, in order: shrinkage as the slab dries in heat without joints cut in time; base movement when water pumps fines out of Myakka sand under an uncompacted base; and loads a 3.5-inch 1960s slab was never built for. Salt and heat get blamed; joints and base are the usual culprits."),
           ("What does proper base prep look like on Myakka fine sand?", "Subgrade dug to firm material and proof-rolled, geotextile where it pumps, 4 to 6 inches of crushed limerock or recycled concrete placed in lifts of 3 inches or less and compacted with a plate compactor to refusal, pitched 1/8 inch per foot to where the water is supposed to go."),
           ("Are hairline cracks a defect?", "Hairline shrinkage cracks that don't offset are normal in concrete and are why joints exist; a crack with a step, or a pattern of cracks across a panel, is a base problem.")]
    body = facts([("Cause 1", "Shrinkage without timely joints"), ("Cause 2", "Base movement from water on sand"), ("Cause 3", "Loads beyond the slab's design"), ("Defense", "Same-day joints, compacted base, 4 in. and 4,000 PSI")])
    body += cap("Why does concrete crack in Sarasota?",
                "Because concrete shrinks as it dries and a 91-degree afternoon dries it fast; if control joints aren't cut the same day at 8 to 10 feet, the slab picks its own crack lines. Because Myakka and EauGallie sands lose fines to water and an uncompacted base drops, taking the slab with it. And because thousands of 1950s to 70s driveways were poured at 3 to 3.5 inches with no base and no joints and have carried SUVs for decades.",
                p("The USDA describes Myakka fine sand as poorly drained with a seasonal high water table within 10 inches for two to six months; NOAA's normals put July and August highs above 91 degrees. Those two facts explain most of the cracks in the county."))
    body += sec("Shrinkage", p("Concrete loses water as it cures and shrinks about 1/16 inch per 10 feet. It will crack; the only question is where. Control joints cut to a quarter of the slab depth at 8 to 10 feet, in panels close to square, give it a place. Cut the next morning in July and the slab has already chosen. Fiber reduces the first-hours plastic shrinkage cracks that appear while the surface is still soft; it doesn't replace joints."))
    body += sec("Base movement", p("Water is the enemy. A downspout onto the base, a sprinkler line leaking under the slab, a swale that stopped draining, a driveway poured on backfill that was never compacted against the garage footing: each one moves sand out from under a panel and the panel drops. The fix is compaction in lifts, a proof roll, geotextile where the sand pumps, and drainage that leaves the lot. On the islands, surge does the same thing in a night."))
    body += sec("Loads", p("A 4-inch slab on a compacted base carries cars for decades. Delivery trucks, boat trailers, dumpsters and skid steers on a 3.5-inch 1960s slab crack it across the middle. Pads and driveways built for those loads are 6 inches with #4 bar."))
    body += sec("What a crack means", table(["Crack", "Likely cause", "Action"], [["Hairline, random, no step", "Shrinkage; joints late or too far apart", "Seal and watch; cosmetic"], ["Straight, at a joint line", "Working as designed", "Nothing"], ["Step across the crack", "Base moved", "Find the water; lift or replace"], ["Corner breaks near the garage", "Uncompacted backfill", "Compact and replace the panel"], ["Map cracking, scaling surface", "Wet finish, salt, poor cure", "Resurface if sound; replace if not"], ["Cracks radiating from a point", "Point load", "Thicker pad for that load"]], "Reading cracks"))
    body += sec("Related", cards([("/compare/rebar-vs-fiber/", "Rebar vs fiber", "What holds cracks shut."), ("/concrete/repair/", "Concrete repair", "Sealing, lifting, replacing."), ("/concrete/driveways/", "Driveways", "The spec that prevents it.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("why-concrete-cracks-sarasota", "Why Concrete Cracks in Sarasota (and What Prevents It)", "The three causes of cracked concrete in Sarasota County (shrinkage without same-day joints, base movement on Myakka sand, loads beyond the slab), how to read a crack, and the base prep and joint spacing that prevent most of them.",
              "Why concrete cracks in Sarasota, and what a crack is telling you", "Heat, sand and old slabs, in that order, and the joints and base that answer them.", body, faq)


def cure():
    faq = [("What happens if it rains on my pour during a July afternoon storm?", "In the first two hours after placement, rain washes cement paste off the surface, weakens the top and leaves dusting and scaling later; the crew covers the slab with plastic and refinishes what it can. After the surface has set (four to eight hours), rain does no harm and helps the cure. That's why summer pours start at 7 a.m."),
           ("How long before I can drive on a new driveway in Sarasota heat?", "Seven days for cars and SUVs, 24 hours for foot traffic, 28 days for trucks, boat trailers and heavy loads. Heat speeds early strength but doesn't shorten the 28-day mark, and it makes the 7-day cure protection more important, not less."),
           ("Does the concrete need to be watered?", "If a curing compound was sprayed, no; if the crew wet-cures, the slab stays damp for 7 days. Letting it dry out in the first week is the fastest way to a weak, dusty surface.")]
    body = facts([("Rain risk", "First 2 hours after placement"), ("Foot traffic", "24 hours"), ("Cars", "7 days"), ("Heavy loads", "28 days")])
    body += cap("When can I walk, drive and park on new concrete, and what does rain do?",
                "Foot traffic after 24 hours, cars after 7 days, heavy vehicles and trailers after 28. Rain in the first two hours after placement washes paste off the surface and weakens it; after the surface sets, rain is harmless. In Sarasota's wet season, with 7 to 9 inches of monthly rain arriving mostly in afternoon storms, pours start at 7 a.m. and are finished and protected by early afternoon.",
                p("Curing is the week after the pour, not the day of it. A curing compound or a wet cure for 7 days is what turns a 4,000 PSI mix into a 4,000 PSI slab; a slab left to dry in the sun reaches a fraction of that at the surface."))
    body += sec("The timeline", table(["Time", "What's happening", "What you can do"], [["0 to 2 h", "Placing, screeding, floating; surface soft", "Nothing; rain is the risk"], ["2 to 8 h", "Setting; finishing and joint cutting", "Keep off it; joints cut in this window"], ["24 h", "Surface hard; about 30% strength", "Walk on it"], ["3 days", "About 50% strength", "Light furniture"], ["7 days", "About 70% strength; cure protection ends", "Cars, SUVs; screen cage anchors"], ["28 days", "Design strength", "Trucks, trailers, heavy pads; sealing"]], "Concrete cure timeline; percentages are typical for a 4,000 PSI mix in warm weather"))
    body += sec("Heat and wind", p("Heat speeds the set and increases evaporation from the surface, which is what causes plastic shrinkage cracks in the first hours. Winter cold fronts bring dry, windy days that evaporate water off a slab faster than July does. Evaporation reducers, shade and an early start are the answers in both seasons."))
    body += sec("Pavers", p("Polymeric sand needs 24 to 48 dry hours after activation or it washes out; you can walk on a paver deck as soon as it's compacted and drive on a paver driveway as soon as the sand cures. Sealing waits 30 days."))
    body += sec("Related", cards([("/tools/pour-calendar/", "Pour calendar", "Month by month."), ("/guides/why-concrete-cracks-sarasota/", "Why concrete cracks", "Shrinkage and joints."), ("/concrete/driveways/", "Driveways", "Spec.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("cure-times-and-rain", "Cure Times & Rain: When to Walk, Drive and Park on New Concrete", "How rain in the first two hours affects a Sarasota pour, when you can walk (24 h), drive (7 days) and park heavy loads (28 days) on new concrete, why a 7-day cure matters in heat and wind, and the paver-sand equivalent.",
              "Cure times, rain and when you can drive on it", "Two hours of rain risk, seven days of cure, twenty-eight days to full strength, and a 7 a.m. start in summer.", body, faq)


def snowbird():
    faq = [("How do you run a job when the owner is out of state for the summer?", "Video estimate, e-signed scope with photos of every decision point, a property manager or neighbor as the on-site contact, daily photo reports, permit and ARC handled by the provider, and a schedule that ends before you fly in. Payment milestones tie to photographed stages."),
           ("What is the lead time in season versus summer?", "January through April: four to eight weeks to a start date, sometimes more. June through September: two to four weeks, with weather shaping pour days. Book summer work in March if you want it done before November."),
           ("How do I get a quote without being home?", "A video walkthrough on your phone or a neighbor's, plus your survey or site plan from closing and a few photos of the surface. That's enough for a written scope; the site visit confirms measurements before the contract is signed.")]
    body = facts([("Season", "Owners present Jan to Apr; away Jun to Sep"), ("Best work window", "May to October"), ("Deadline", "Finished before November"), ("Tools", "Video estimate, e-sign, daily photos, manager hand-off")])
    body += cap("How does a seasonal owner get a driveway or pool deck done while away?",
                "Decide in March, sign in April, build in the summer, come back in November to a finished job. The provider quotes from a video walkthrough and your survey, sends a scope you sign electronically, pulls the permit and prepares the ARC packet, works with your property manager or a neighbor as the on-site contact, sends photos every working day, and ties payments to photographed milestones. Summer lead times are the shortest of the year.",
                p("Sarasota County's population rises past 570,000 in winter and drops in summer; the crews' calendars follow. The owner who books in March gets the calendar and the price; the owner who calls in December gets a waiting list."))
    body += sec("The twelve-month version", table(["Month", "Step"], [["January to February", "Walk the property while you're here; photograph the surfaces; note what you want"], ["March", "Request the estimate; site visit while you're still in town; ARC packet drafted"], ["April", "Sign the scope; ARC submitted; permit application filed; deposit"], ["May", "Approvals in; materials ordered; start date set"], ["June to September", "Work, with daily photos; polymeric sand and sealing scheduled around dry gaps"], ["October", "Final inspection; care sheet; warranty issued; photos on file"], ["November", "You arrive to a finished deck"]], "Snowbird project calendar"))
    body += sec("What the provider handles remotely", ul(["Permit application and inspections.", "ARC packet preparation (you sign and submit; most associations require the owner).", "Utility locates, irrigation shut-off and re-run.", "Neighbor notice for street parking and noise.", "Daily photo reports and a weekly summary.", "Hand-off to the property manager: care sheet, sealing date, warranty."]))
    body += sec("What you handle", ul(["The survey or site plan from your closing.", "The association's current guidelines and your signature on the ARC form.", "Access: gate code, cage door, water and power.", "Decisions on color and pattern before you leave, with samples in hand.", "Insurance notice if the work is on a barrier island in a flood zone."]))
    body += sec("Related", cards([("/contact/", "Request a video estimate", "Start here."), ("/guides/deposits-and-warranties/", "Deposits and warranties", "What to sign."), ("/hoa/", "HOA and ARC", "The packet.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("snowbird-project-guide", "Snowbird Guide: Sarasota Hardscape Jobs From Out of State", "How seasonal owners get a driveway, patio or pool deck built in Sarasota while away: decide in March, sign in April, build in summer, return in November; video estimates, e-signed scope, permits and ARC handled, daily photos, manager hand-off.",
              "The snowbird project guide: decide in March, come back to a finished deck in November", "Video estimate, e-signed scope, daily photos and a schedule built around the season you're not here.", body, faq)


def deposits():
    faq = [("How much deposit is normal for a concrete or paver job in Florida and what should the contract say?", "For residential work, a modest deposit (often 10 to 30 percent) with the balance in progress payments tied to stages is normal; Florida Statute 489.126 requires a contractor who takes more than 10 percent to apply for the permit within 30 days and start work within 90 days of permits issuing, and a contractor who takes a deposit and doesn't perform faces criminal exposure. The contract states the legal name, license or registration, scope, price, payment schedule, start and completion windows, warranty and the lien-law notice."),
           ("What should a written warranty cover for pavers and concrete?", "Workmanship: base failure, joints cut late, scaling from a bad finish, settled pavers, edge restraint failure, joint sand loss in the first season. Excluded, normally: hairline shrinkage cracks, color variation, damage from vehicles over the design load, tree roots, storm surge, efflorescence, stains from irrigation or salt. Manufacturer warranties on pavers and sealers are separate documents."),
           ("What is the lien-law notice?", "Florida's construction lien law requires a notice in contracts over $2,500 explaining that subcontractors and suppliers can lien your property if the contractor doesn't pay them; a Notice of Commencement recorded for jobs over $5,000 and releases of lien with each payment protect you.")]
    body = facts([("Deposit", "Modest; Florida Statute 489.126 rules apply over 10%"), ("Payments", "Tied to photographed stages"), ("Contract over $2,500", "Lien-law notice"), ("Job over $5,000", "Notice of Commencement; lien releases")])
    body += cap("What should a deposit and a contract look like for hardscape in Florida?",
                "A deposit that's a fraction of the price, a payment schedule tied to stages you can see (demolition done, base inspected, pour or laying complete, final), and a contract that names the legal entity, its license or county registration, the scope with quantities and spec, price, start and completion windows, warranty terms and the lien-law notice Florida requires over $2,500. Under Florida Statute 489.126, a contractor who takes more than 10 percent must apply for permits within 30 days and start within 90 days of issuance.",
                p("A contractor who wants half up front for flatwork, won't put the payment schedule in writing, or won't name the entity is telling you how the job will go."))
    body += sec("The contract checklist", ol(["Legal name of the contractor, its license or Sarasota County certificate number, and insurance certificate.", "Scope: square footage, thickness or paver system, base depth and material, reinforcement, joints, drainage, demolition, disposal.", "Materials by manufacturer, product and color.", "Permit and ARC responsibility and who pays fees.", "Price, deposit, progress payments tied to stages, final payment on completion.", "Start window and completion window, with the weather clause stated plainly.", "Warranty: what's covered, for how long, how to claim.", "Lien-law notice (over $2,500); Notice of Commencement and lien releases (over $5,000).", "Change-order process in writing."]))
    body += sec("Related", cards([("/warranty/", "Warranty", "What the provider's terms cover."), ("/guides/verify-contractor-license-sarasota/", "Verify a contractor", "Before you sign."), ("/financing/", "Financing", "Payment schedules.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("deposits-and-warranties", "Deposits, Contracts & Warranties for Florida Hardscape", "What a deposit, payment schedule and contract should look like for a concrete or paver job in Florida: Statute 489.126 deposit rules, the lien-law notice, Notice of Commencement, a contract checklist and what a workmanship warranty should cover and exclude.",
              "Deposits, contracts and warranties: what to sign and what to refuse", "A modest deposit, payments you can photograph, a legal name on the page and a warranty you can read.", body, faq)


def verify():
    faq = [("How do I verify a concrete contractor's license in Sarasota County?", "Check the state first at myfloridalicense.com (DBPR) for a certified or registered contractor license; then check Sarasota County's contractor registration and Certificate of Competency through the county's licensing office, because Code Chapter 22 requires an Operating Certificate and Certificate of Competency for regulated trades; then ask for the certificate of insurance and the surety bond the county requires for registration."),
           ("Does a paver installer need a state license in Florida?", "No. Installing driveways and pavers is on the DBPR's list of work that doesn't require a state construction license. Counties and cities can require local registration or a competency card, and Sarasota and Charlotte counties do for regulated trades; Charlotte's Local Concrete Masonry license is one example."),
           ("What insurance should a concrete contractor show me?", "A certificate of general liability insurance naming you or the county as certificate holder, workers' compensation or a valid exemption, and, for county registration, the surety bond the county requires by category. Ask for the certificate directly from the insurer's agent, not a photocopy.")]
    body = facts([("State", "DBPR license lookup (myfloridalicense.com)"), ("County", "Sarasota County Operating Certificate + Certificate of Competency (Code Ch. 22)"), ("Charlotte", "Local Concrete Masonry or state license"), ("Always", "Insurance certificate, bond, permit history")])
    body += cap("How do I check a contractor before signing?",
                "Four lookups. The DBPR license search for a state license (not required for flatwork and pavers, but common); Sarasota County's contractor licensing office for the Operating Certificate and Certificate of Competency that Code Chapter 22 requires for regulated trades; the permit portal for the contractor's permit history and any citations; and the insurer's agent for a current certificate of liability and workers' compensation. Charlotte County accepts a Local Concrete Masonry license for driveway and slab permits.",
                p("Florida Statute 489.119(5)(b) requires a licensed contractor to put its license number on every advertisement, proposal and contract; a company that advertises \"licensed\" without a number is either unlicensed or careless. This site says \"Insured\" and nothing more until the provider's number is documented, which is the same standard you should hold everyone to."))
    body += sec("The four lookups", table(["What", "Where", "What you're looking for"], [["State license", "myfloridalicense.com, DBPR license search", "Active status, no discipline; the name matches the contract"], ["County registration and competency", "Sarasota County Planning & Development contractor licensing; Charlotte County Contractor Licensing", "Active Operating Certificate and Certificate of Competency in a relevant category"], ["Permit history", "building.scgov.net; city portals; Charlotte County records", "Permits pulled in the contractor's name; no unresolved violations"], ["Insurance and bond", "Certificate from the agent", "General liability, workers' comp or exemption, surety bond"]], "Verifying a contractor in Sarasota and Charlotte counties"))
    body += sec("Red flags", ul(["No legal entity name on the estimate.", "\"Licensed\" with no number.", "Asks you to pull the permit as owner-builder for work they're doing.", "Wants most of the money before demolition.", "Won't put the base depth or the joint spacing in writing.", "Can't produce an insurance certificate from the agent."]))
    body += sec("Related", cards([("/guides/deposits-and-warranties/", "Deposits and contracts", "What to sign."), ("/permits/sarasota-county/", "Sarasota County permits", "Contractor registration rules."), ("/about/", "About this site", "What we don't claim.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("verify-contractor-license-sarasota", "How to Verify a Concrete or Paver Contractor in Sarasota County", "Four lookups before you sign with a concrete or paver contractor in Sarasota or Charlotte County: DBPR state license, county Operating Certificate and Certificate of Competency, permit history, insurance and bond, plus the statute on license numbers in advertising.",
              "How to verify a contractor in Sarasota County before you sign", "State license if any, county registration and competency, permit history, insurance and bond. Four lookups, twenty minutes.", body, faq)


def rust():
    faq = [("How do I remove rust stains from well-water irrigation on pavers?", "With an oxalic-acid cleaner diluted per the label, applied with a pump sprayer, allowed to dwell without drying, lightly agitated and rinsed; test a corner first, keep it off travertine and marble (acid etches limestone), and expect to reseal afterward because rust removers strip most sealers."),
           ("How do I stop it coming back?", "Redirect or replace sprinkler heads so the spray doesn't cross the hardscape; add an iron filter or a sequestering-agent injector to the well irrigation system; seal the surface so iron sits on top of the sealer instead of in the pore."),
           ("Is it a problem east of I-75 only?", "Mostly. Fruitville, Bee Ridge, Nokomis east of the interstate, South Venice, North Port and much of Charlotte County irrigate from wells with dissolved iron; city water lots rarely see it.")]
    body = facts([("Cause", "Dissolved iron in well water oxidizing on the surface"), ("Where", "Well-irrigated lots east of I-75 and in South Venice, North Port, Charlotte"), ("Removal", "Oxalic-acid cleaner; not on limestone"), ("Prevention", "Head redirection, iron filter, sealer")])
    body += cap("Why does my driveway turn orange, and how do I fix it?",
                "Well water in this county carries dissolved iron; sprayed through sprinklers it meets air, oxidizes and drops rust on whatever it lands on. Removal is an oxalic-acid cleaner on concrete and concrete pavers (never on travertine, shellstone or marble, which acid etches), tested on a corner, dwelled, agitated and rinsed, followed by resealing. Prevention is heads that don't cross the hardscape, an iron filter or sequestering injector on the well system, and a penetrating sealer.",
                p("The stain is cosmetic; it doesn't hurt the concrete. Sealer that was already on the surface takes the stain instead of the pore, which is why sealed driveways clean up and unsealed ones hold the orange. For scale: the EPA's secondary drinking-water standard for iron is 0.3 mg/L, and irrigation wells east of I-75 commonly test at 1 to 5 mg/L; oxalic-acid cleaners are typically diluted 8:1 to 10:1 with water and dwell 5 to 10 minutes; a 600-square-foot driveway takes about 2 hours to clean and a day to dry before resealing."))
    body += sec("Removal by surface", table(["Surface", "Cleaner", "Notes"], [["Broom or textured concrete", "Oxalic acid (diluted per label)", "Reseal after"], ["Concrete pavers", "Oxalic acid", "Reseal; re-sand if joints are disturbed"], ["Travertine, shellstone, marble", "Neutral-pH rust remover made for natural stone", "No acid; test first"], ["Porcelain", "Almost anything", "Immune"], ["Stamped or sealed decorative", "Strip, clean, reseal", "Rust remover takes the sealer with it"]], "Rust stain removal"))
    body += sec("Prevention", ol(["Walk the irrigation zones and note every head whose spray crosses a slab or paver field; redirect, replace with a shorter-throw nozzle, or move it.", "Test the well water for iron; above about 0.3 ppm, an iron filter or a sequestering agent injector on the irrigation line is the durable fix.", "Seal the hardscape with a penetrating sealer so stains stay on the surface.", "Rinse the surface after any irrigation change."]))
    body += sec("Related", cards([("/pavers/sealing/", "Cleaning and sealing", "The service."), ("/compare/sealer-types-coastal/", "Sealer types", "Which one."), ("/areas/fruitville-bee-ridge/", "Fruitville and Bee Ridge", "Where wells are common.")]))
    body += faq_block(faq)
    body += reviewed("September 10, 2026")
    return pg("well-water-rust-stains", "Rust Stains From Well-Water Irrigation on Pavers & Driveways", "Why well-irrigated lots in Sarasota County get orange rust stains on driveways and pavers, how to remove them by surface (oxalic acid on concrete, never on limestone), and how to stop them with head redirection, iron filtration and sealer.",
              "Rust stains from well-water irrigation: removal by surface and prevention at the sprinkler", "Iron in the well, oxygen in the spray, orange on the slab. The fix is the sprinkler head, then the cleaner, then the sealer.", body, faq)


def sand():
    faq = [("What is polymeric sand and when should it be replaced?", "Fine sand mixed with a polymer binder that hardens when wetted, locking pavers together and resisting wash-out, weeds and ants. A properly installed full-depth joint lasts 8 to 12 years or more; shallow or badly drained joints fail in 3 to 5. It's topped up when joints drop more than a quarter inch and replaced when the field is lifted."),
           ("Why do weeds and ants keep coming back between my pavers?", "Because the joint sand is gone or was plain sand. Weeds seed into open joints from above, not up from below; ants tunnel where sand is loose. Cleaning the joints out and installing polymeric sand to full depth, activated on a dry day, ends most of it; sealing on top helps."),
           ("Can polymeric sand be installed in the rainy season?", "On a two-day dry forecast. Rain in the first 24 hours after activation reactivates the polymer and washes it out, leaving a haze on the pavers and empty joints.")]
    body = facts([("What it is", "Sand plus a polymer binder that sets when wetted"), ("Life", "8 to 12 years full depth; 3 to 5 if shallow or wet"), ("Weeds", "Seed from above into empty joints"), ("Install", "Dry pavers, full depth, activate, 24 to 48 dry hours")])
    body += cap("What does polymeric sand do, and why do weeds mean it's gone?",
                "It fills the joints between pavers and, once activated with water, sets into a firm but flexible seal that locks the units, resists wash-out and blocks weeds and ants. Weeds seed into open joints from above, so a weedy paver field is a field whose joint sand is missing or was plain sand. Full-depth joints last 8 to 12 years when the base drains; they're topped up when they drop a quarter inch.",
                p("The most common failure is installation: sand swept into damp pavers, activated too heavily, or rained on within a day. Done right on a dry surface with a two-day dry forecast, it's the least expensive thing that keeps a paver field looking installed."))
    body += sec("Installation, step by step", ol(["Pavers dry and clean; joints emptied to at least two-thirds of the paver depth.", "Sand swept into the joints, then compacted with a plate compactor and a pad so the sand settles.", "Second sweep to fill; surface blown or swept clean so no sand dust is left on the face (it hazes).", "Activation with a fine mist in passes, never a stream; the polymer sets as it dries.", "24 to 48 dry hours before rain or irrigation; longer for thick joints."]))
